var kthSmallest = function(matrix, k) {
    const n = matrix.length;
    let low = matrix[0][0], high = matrix[n - 1][n - 1];

    function countLE(mid) {
        let count = 0;
        let r = n - 1, c = 0;
        while (r >= 0 && c < n) {
            if (matrix[r][c] <= mid) {
                count += r + 1;
                c++;
            } else {
                r--;
            }
        }
        return count;
    }

    let ans = low;
    while (low <= high) {
        const mid = Math.floor((low + high) / 2);
        if (countLE(mid) >= k) {
            ans = mid;
            high = mid - 1;
        } else {
            low = mid + 1;
        }
    }
    return ans;
};
